-- The migrations V221 to V240 in order, folded in so a new database needs no catch-up at startup.
-- 09_migration_history.sql marks them done. sql/migration keeps the files for servers updating from older versions.


-- ----------------------------------------------------------------------------------------------------
-- V221_Power_Item_Drop_Rates.sql
-- Nodestones and Arcane/Sacred Symbols drop twice as often.
UPDATE mob_drops SET chance = LEAST(10000, chance * 2)
WHERE itemid IN (2435719, 2435902, 2436078, 2436324, 2439869, 2631128)
   OR itemid BETWEEN 1712000 AND 1713999;


-- ----------------------------------------------------------------------------------------------------
-- V222_Boss_Drop_Counts_GMS_v271.sql
-- Boss drop amounts raised to what GMS v271 drops per kill (each drop object holds at least one, so these
-- counts are minimums): Chaos Root Abyss pieces, Cygnus's Pieces of Ruin/Darkness, Hard Magnus's coins.
UPDATE mob_drops SET minquant = 8, maxquant = 8 WHERE mobid = 8900003 AND itemid = 2434585;  -- Chaos Pierre
UPDATE mob_drops SET minquant = 9, maxquant = 9 WHERE mobid = 8910000 AND itemid = 2434584;  -- Chaos Von Bon
UPDATE mob_drops SET minquant = 11, maxquant = 11 WHERE mobid = 8920006 AND itemid = 2434586; -- Chaos Crimson Queen
UPDATE mob_drops SET minquant = 9, maxquant = 10 WHERE mobid = 8930000 AND itemid = 2434587;  -- Chaos Vellum
UPDATE mob_drops SET minquant = 9, maxquant = 9 WHERE mobid = 8850011 AND itemid = 2434588;   -- Cygnus: Piece of Ruin
UPDATE mob_drops SET minquant = 11, maxquant = 11 WHERE mobid = 8850011 AND itemid = 2434589; -- Cygnus: Piece of Darkness
UPDATE mob_drops SET chance = 10000, minquant = 9, maxquant = 9 WHERE mobid = 8880000 AND itemid = 4310058; -- Hard Magnus: Magnus Coin
UPDATE mob_drops SET chance = 10000, minquant = 6, maxquant = 6 WHERE mobid = 8880000 AND itemid = 4310059; -- Hard Magnus: Shadowdealer Coin


-- ----------------------------------------------------------------------------------------------------
-- V223_Grandis_Symbol_Drops.sql
-- Grandis monsters drop their area's untradable symbol coupon, as in GMS (the same coupon the area's daily quest
-- gives; double-click for the symbol). Cernium and Arcus dropped the symbol itself until now.
UPDATE mob_drops SET itemid = 2636137 WHERE itemid = 1713000; -- Cernium
UPDATE mob_drops SET itemid = 2636138 WHERE itemid = 1713001; -- Arcus

-- Mob ids from the v271 map spawns of each area; chance as the other symbol drops.
INSERT INTO mob_drops (mobid, itemid, chance, minquant, maxquant)
SELECT m.mobid, m.itemid, 990, 1, 1
FROM (
    -- Odium: Sacred Symbol: Odium Coupon
    SELECT 8645290 AS mobid, 2636320 AS itemid UNION ALL SELECT 8645291, 2636320 UNION ALL SELECT 8645292, 2636320
    UNION ALL SELECT 8645293, 2636320 UNION ALL SELECT 8645294, 2636320 UNION ALL SELECT 8645295, 2636320
    UNION ALL SELECT 8645296, 2636320 UNION ALL SELECT 8645297, 2636320 UNION ALL SELECT 8645298, 2636320
    UNION ALL SELECT 8645299, 2636320
    -- Shangri-La
    UNION ALL SELECT 8645365, 2636321 UNION ALL SELECT 8645366, 2636321 UNION ALL SELECT 8645367, 2636321
    UNION ALL SELECT 8645368, 2636321 UNION ALL SELECT 8645369, 2636321 UNION ALL SELECT 8645370, 2636321
    UNION ALL SELECT 8645371, 2636321 UNION ALL SELECT 8645372, 2636321
    -- Arteria (Empress Road + Arteria)
    UNION ALL SELECT 8645400, 2636395 UNION ALL SELECT 8645401, 2636395 UNION ALL SELECT 8645402, 2636395
    UNION ALL SELECT 8645403, 2636395 UNION ALL SELECT 8645404, 2636395 UNION ALL SELECT 8645405, 2636395
    -- Carcion
    UNION ALL SELECT 8645420, 2636553 UNION ALL SELECT 8645421, 2636553 UNION ALL SELECT 8645422, 2636553
    UNION ALL SELECT 8645423, 2636553 UNION ALL SELECT 8645424, 2636553 UNION ALL SELECT 8645425, 2636553
    UNION ALL SELECT 8645426, 2636553 UNION ALL SELECT 8645427, 2636553
    -- Tallahart: Grand Sacred Symbol: Tallahart Coupon
    UNION ALL SELECT 8645460, 2638105 UNION ALL SELECT 8645461, 2638105 UNION ALL SELECT 8645462, 2638105
    UNION ALL SELECT 8645463, 2638105 UNION ALL SELECT 8645464, 2638105 UNION ALL SELECT 8645465, 2638105
    UNION ALL SELECT 8645466, 2638105
    -- Geardock: Grand Sacred Symbol: Geardock Coupon
    UNION ALL SELECT 8645481, 2831353 UNION ALL SELECT 8645482, 2831353 UNION ALL SELECT 8645483, 2831353
    UNION ALL SELECT 8645484, 2831353 UNION ALL SELECT 8645485, 2831353 UNION ALL SELECT 8645486, 2831353
) m
WHERE NOT EXISTS (SELECT 1 FROM mob_drops d WHERE d.mobid = m.mobid AND d.itemid = m.itemid);


-- ----------------------------------------------------------------------------------------------------
-- V224_Princess_No_Drops_GMS_v271.sql
-- Princess No (9450022) drops as GMS v271 (two kills agree): no more Jewel Boxes (old event boxes the
-- client won't open); Captivating Fragments, Mystical Cubes, Boss Medals of Honor and Twisted Time instead.
-- Counts are drop objects per kill (each holds at least one).
DELETE FROM mob_drops WHERE mobid = 9450022 AND itemid IN (2432754, 2432755, 2433103, 2630594, 2710033, 4021031);
-- Captivating Fragment, Mystical Cube, Boss Medal of Honor, Twisted Time (the migration runner can't take a comment
-- at the end of a line inside a statement)
INSERT INTO mob_drops (mobid, itemid, chance, minquant, maxquant) VALUES
    (9450022, 2630594, 10000, 5, 6),
    (9450022, 2710033, 10000, 13, 13),
    (9450022, 2433103, 10000, 15, 15),
    (9450022, 4021031, 10000, 1, 1);


-- ----------------------------------------------------------------------------------------------------
-- V225_Pull_Broken_Shop_Items.sql
-- Items that don't work yet come out of the shops until they do (plans/features/pulled-items.tsv says when they return).
-- Violet Cube: no pick-from-six handling.
DELETE FROM shopitems WHERE itemid = 5062024 AND shopid IN (9010038, 9010040);
-- Potential Stamps: retired items whose Power Elixir exchange script doesn't exist yet, so using one does nothing.
DELETE FROM shopitems WHERE itemid = 2049500 AND shopid = 9001174;
DELETE FROM shopitems WHERE itemid = 2049506 AND shopid = 9010038;
DELETE FROM shopitems WHERE itemid = 2049509 AND shopid IN (9010107, 9010111);
DELETE FROM shopitems WHERE itemid = 2048212 AND shopid = 9010038;


