WHERE type = 0 AND iscash = 0 AND itemid IN (
    1000039, 1000040, 1000054, 1000055, 1000056, 1000057, 1000063, 1000065, 1000066, 1000067, 1000068, 1000150, 1000151, 1001059, 1001060, 1001079, 1001080, 1001081, 1001177, 1001178,
