-- V228_Drops_Missing_Ids.sql
-- Drop rows pointing at items or monsters the v271 data doesn't have.

-- familiar cards gone from Item.wz: the mob's v271 card (Character.wz Familiar MobID) where it has one
INSERT INTO mob_drops (mobid, itemid, chance, minquant, maxquant) SELECT mobid, 2880583, chance, minquant, maxquant FROM mob_drops a WHERE a.mobid = 9400590 AND a.itemid = 2870513 AND NOT EXISTS (SELECT 1 FROM (SELECT mobid, itemid FROM mob_drops) b WHERE b.mobid = 9400590 AND b.itemid = 2880583);
INSERT INTO mob_drops (mobid, itemid, chance, minquant, maxquant) SELECT mobid, 2880584, chance, minquant, maxquant FROM mob_drops a WHERE a.mobid = 9400591 AND a.itemid = 2870515 AND NOT EXISTS (SELECT 1 FROM (SELECT mobid, itemid FROM mob_drops) b WHERE b.mobid = 9400591 AND b.itemid = 2880584);
INSERT INTO mob_drops (mobid, itemid, chance, minquant, maxquant) SELECT mobid, 2880586, chance, minquant, maxquant FROM mob_drops a WHERE a.mobid = 9400593 AND a.itemid = 2870516 AND NOT EXISTS (SELECT 1 FROM (SELECT mobid, itemid FROM mob_drops) b WHERE b.mobid = 9400593 AND b.itemid = 2880586);
DELETE FROM mob_drops WHERE itemid IN (2870512, 2870513, 2870515, 2870516, 2870523, 2870996, 2870997, 2870998, 2870999,
    2871026, 2871188, 2871189, 2871190, 2871191, 2871192, 2880554, 2880555, 2880558, 2880560, 2880561, 2880562,
    2880564, 2880664);

-- mob ids written as item ids (King Sage Cat, Melon Bubble Tea)
DELETE FROM mob_drops WHERE itemid IN (2600305, 3400002);
DELETE FROM mob_drops WHERE mobid = 0 AND itemid = 0;

-- Crimson Queen's old final-phase ids: their drops belong to the v271 final body
INSERT INTO mob_drops (mobid, itemid, chance, minquant, maxquant) SELECT a.mobid + 3, a.itemid, a.chance, a.minquant, a.maxquant FROM mob_drops a WHERE a.mobid IN (8920003, 8920103) AND NOT EXISTS (SELECT 1 FROM (SELECT mobid, itemid FROM mob_drops) b WHERE b.mobid = a.mobid + 3 AND b.itemid = a.itemid);

-- monsters missing from Mob.wz
DELETE FROM mob_drops WHERE mobid IN (1000041, 1000044, 4034527, 8220037, 8290099, 8920003, 8920103, 9101054, 9101127,
    9101128, 9270030);


-- ----------------------------------------------------------------------------------------------------
-- V229_Hidden_Map_Drops.sql
-- Hidden hunting maps without drops: their monsters drop what the same monster of their area's regular maps drops
-- (Arcane Symbols, spell essences, potions); quest items left out.

-- Hidden Cave (450001262): Arma's Follower 8641015 as 8641009
INSERT INTO mob_drops (mobid, itemid, chance, minquant, maxquant) SELECT 8641015, a.itemid, a.chance, a.minquant, a.maxquant FROM mob_drops a WHERE a.mobid = 8641009 AND NOT EXISTS (SELECT 1 FROM (SELECT mobid, itemid FROM mob_drops) b WHERE b.mobid = 8641015 AND b.itemid = a.itemid);

-- Hidden Plate Street (450003360): Crooked Victory Plate 8643014-8643016 as 8643006
INSERT INTO mob_drops (mobid, itemid, chance, minquant, maxquant) SELECT m.id, a.itemid, a.chance, a.minquant, a.maxquant FROM mob_drops a JOIN (SELECT 8643014 AS id UNION ALL SELECT 8643015 UNION ALL SELECT 8643016) m WHERE a.mobid = 8643006 AND a.itemid NOT IN (4034982, 4034983, 4034984, 4034985, 4034986, 4034987, 4034988, 4036572) AND NOT EXISTS (SELECT 1 FROM (SELECT mobid, itemid FROM mob_drops) b WHERE b.mobid = m.id AND b.itemid = a.itemid);


-- ----------------------------------------------------------------------------------------------------
-- V230_Bare_Mob_Drops.sql
-- Hunting-map monsters with no drop rows of their own: the rows of the same monster (same name, within 15
-- levels) that has them.
INSERT INTO mob_drops (mobid, itemid, chance, minquant, maxquant) SELECT m.mobid, a.itemid, a.chance, a.minquant, a.maxquant
FROM mob_drops a JOIN (
    SELECT 2300101 AS mobid, 9300736 AS donor
    UNION ALL SELECT 2300260 AS mobid, 2300271 AS donor
    UNION ALL SELECT 2400311 AS mobid, 2400318 AS donor
    UNION ALL SELECT 4310022 AS mobid, 4310005 AS donor
    UNION ALL SELECT 4310023 AS mobid, 4310007 AS donor
    UNION ALL SELECT 4310024 AS mobid, 4310009 AS donor
    UNION ALL SELECT 4310025 AS mobid, 4310011 AS donor
    UNION ALL SELECT 4310026 AS mobid, 4310014 AS donor
    UNION ALL SELECT 5100103 AS mobid, 5100005 AS donor
    UNION ALL SELECT 8140555 AS mobid, 8230025 AS donor
    UNION ALL SELECT 8147015 AS mobid, 8147007 AS donor
    UNION ALL SELECT 8190001 AS mobid, 8190000 AS donor
    UNION ALL SELECT 8211005 AS mobid, 8211000 AS donor
    UNION ALL SELECT 8211006 AS mobid, 8211001 AS donor
    UNION ALL SELECT 8211007 AS mobid, 8211002 AS donor
    UNION ALL SELECT 8620028 AS mobid, 8620000 AS donor
    UNION ALL SELECT 8620029 AS mobid, 8620003 AS donor
    UNION ALL SELECT 8620030 AS mobid, 8620010 AS donor
    UNION ALL SELECT 8620031 AS mobid, 8620011 AS donor
    UNION ALL SELECT 8643016 AS mobid, 8643011 AS donor
    UNION ALL SELECT 9390843 AS mobid, 9390808 AS donor
    UNION ALL SELECT 9390845 AS mobid, 9390810 AS donor
    UNION ALL SELECT 9390846 AS mobid, 9390811 AS donor
    UNION ALL SELECT 9400015 AS mobid, 9400039 AS donor
    UNION ALL SELECT 9400030 AS mobid, 9400000 AS donor
) m ON a.mobid = m.donor
WHERE NOT EXISTS (SELECT 1 FROM (SELECT mobid FROM mob_drops) b WHERE b.mobid = m.mobid);


